// Minimal endless runner based on IDEA.md
// Canvas with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.offsetWidth;
  const height = canvas.height = canvas.offsetHeight;

  // Game settings
  const GRAVITY = 0.6;
  const JUMP_VELOCITY = -12;
  const PLAYER_SIZE = 10;
  const OBSTACLE_WIDTH = 15;
  const OBSTACLE_GAP = 120; // distance between obstacles
  const OBSTACLE_SPEED = 3;

  let score = 0;
  let frame = 0;

  const player = {
    x: 50,
    y: height - PLAYER_SIZE,
    vy: 0,
    width: PLAYER_SIZE,
    height: PLAYER_SIZE,
    onGround: true,
  };

  const obstacles = [];

  // Input – tap / click to jump
  const jump = () => {
    if (player.onGround) {
      player.vy = JUMP_VELOCITY;
      player.onGround = false;
    }
  };
  canvas.addEventListener('click', jump);
  canvas.addEventListener('touchstart', e => { e.preventDefault(); jump(); });

  const spawnObstacle = () => {
    const height = Math.random() * (height * 0.5) + 20; // random height
    obstacles.push({
      x: width,
      y: height > height / 2 ? 0 : height - height, // simple top or bottom obstacle
      w: OBSTACLE_WIDTH,
      h: height,
    });
  };

  const update = () => {
    // Player physics
    player.vy += GRAVITY;
    player.y += player.vy;
    if (player.y + player.height >= height) {
      player.y = height - player.height;
      player.vy = 0;
      player.onGround = true;
    }

    // Move obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= OBSTACLE_SPEED;
      // Remove off‑screen
      if (o.x + o.w < 0) {
        obstacles.splice(i, 1);
        score++;
      } else {
        // Collision detection
        const collides =
          player.x < o.x + o.w &&
          player.x + player.width > o.x &&
          player.y < o.y + o.h &&
          player.y + player.height > o.y;
        if (collides) {
          // Game over – stop animation
          cancelAnimationFrame(animationId);
          alert('Game Over! Score: ' + score);
          return;
        }
      }
    }

    // Spawn new obstacles at intervals
    if (frame % Math.round(OBSTACLE_GAP / OBSTACLE_SPEED) === 0) {
      spawnObstacle();
    }
    frame++;
  };

  const draw = () => {
    ctx.clearRect(0, 0, width, height);
    // Player
    ctx.fillStyle = '#0f0';
    ctx.fillRect(player.x, player.y, player.width, player.height);
    // Obstacles
    ctx.fillStyle = '#f00';
    obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
    // Score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
  };

  let animationId;
  const loop = () => {
    update();
    draw();
    animationId = requestAnimationFrame(loop);
  };
  loop();
})();
